// Where a deployed console points, read before anything else loads.
//
// Two ways a console is deployed, two files that say where it points:
//   - `config.js`, written by the `dutyboard` provisioner, sets window.DUTYBOARD_CONFIG itself;
//   - `/altengine.json`, generated by altengine when DutyBoard is deployed from its manifest
//     ("Deploy to altengine"), lists the app's instances. It is read here and turned into the same
//     shape, so src/config.js has one thing to read either way.
// Neither, as on the dev server, leaves the build's own VITE_* values in charge.

/** window.DUTYBOARD_CONFIG from an altengine runtime config, or null when it is not one of ours. */
export function fromAltengineJson(j) {
  const inst = (j && j.instances) || {};
  const fns = inst.functions;
  if (!fns || !fns.url || !inst.auth || !inst.datastore) return null;
  return {
    baseUrl: String(j.api || "").replace(/\/+$/, ""),
    // Sign-in carries no key, so hosted auth is addressed by id; see src/config.js.
    auth: inst.auth.id || inst.auth.name,
    datastore: inst.datastore.name,
    channel: inst.live ? inst.live.name : "",
    functions: fns.name,
    api: `${String(fns.url).replace(/\/+$/, "")}/board`,
    fn: "board",
    // Which app this is and at what version, for "an update is out".
    app: j.app || "",
    version: j.version || "",
  };
}

export async function loadRuntimeConfig() {
  if (typeof window === "undefined" || window.DUTYBOARD_CONFIG) return;
  try {
    const res = await fetch("./altengine.json", { cache: "no-store" });
    if (!res.ok) return;
    const cfg = fromAltengineJson(await res.json());
    if (cfg) window.DUTYBOARD_CONFIG = cfg;
  } catch {
    // Not deployed from a manifest (or not JSON): the build's defaults stand.
  }
}
